import java.util.Scanner;

public class Main {
    static long[] sequence = new long[20];
    static int min_moves;

    static long extract_leading(long number, int[] length) {
        length[0] = 0;
        while (number >= 10) {
            number /= 10;
            length[0]++;
        }
        return number;
    }

    static void dfs(long value, int steps) {
        if (steps >= min_moves) return;
        if (value == 0) {
            min_moves = steps;
            return;
        }
        int[] lenArr = new int[1];
        int len;
        int lead = (int) extract_leading(value, lenArr);
        len = lenArr[0];
        dfs(Math.abs(value - sequence[len] * lead), steps + lead * (len + 1));
        if (lead - 1 > 0)
            dfs(Math.abs(value - sequence[len] * (lead - 1)), steps + (lead - 1) * (len + 1));
        if (lead > 1)
            dfs(Math.abs(sequence[len + 1] - value), steps + (len + 2));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        sequence[0] = 1;
        for (int i = 1; i <= 18; i++) {
            sequence[i] = sequence[i - 1] * 10 + 1;
        }
        min_moves = Integer.MAX_VALUE;
        dfs(n, 0);
        System.out.println(min_moves);
        sc.close();
    }
}
